hl.config({ animations = { enabled = true } })
hl.curve("navuryxEase", { type = "bezier", points = { {0.22, 1}, {0.36, 1} } })
hl.curve("navuryxFast", { type = "bezier", points = { {0.16, 1}, {0.3, 1} } })
hl.curve("navuryxSpring", { type = "spring", mass = 1, stiffness = 250, dampening = 25 })
hl.animation({ leaf = "global", enabled = true, speed = 8, bezier = "navuryxEase" })
hl.animation({ leaf = "windows", enabled = true, speed = 5.2, spring = "navuryxSpring" })
hl.animation({ leaf = "windowsIn", enabled = true, speed = 4.5, spring = "navuryxSpring", style = "popin 88%" })
hl.animation({ leaf = "windowsOut", enabled = true, speed = 2.2, bezier = "navuryxFast", style = "popin 88%" })
hl.animation({ leaf = "border", enabled = true, speed = 5, bezier = "navuryxEase" })
hl.animation({ leaf = "fade", enabled = true, speed = 4, bezier = "navuryxFast" })
hl.animation({ leaf = "layers", enabled = true, speed = 4, bezier = "navuryxEase" })
hl.animation({ leaf = "workspaces", enabled = true, speed = 4, bezier = "navuryxEase", style = "slide" })
